import 'package:firebase_storage/firebase_storage.dart';
import 'dart:io';

final storage = FirebaseStorage.instance;

// ────── UPLOAD from File ──────
final ref = storage.ref('users/$uid/avatar.jpg');

final metadata = SettableMetadata(
  contentType: 'image/jpeg',
  customMetadata: {'uploadedBy': uid, 'source': 'camera'},
);

final task = ref.putFile(file, metadata);

// Progress + cancel/pause/resume:
final sub = task.snapshotEvents.listen((snap) {
  final progress = snap.bytesTransferred / snap.totalBytes;
  print('${(progress * 100).toStringAsFixed(1)}%');
  if (snap.state == TaskState.paused) print('paused');
});

// Wait for completion:
try {
  final result = await task;
  final downloadUrl = await result.ref.getDownloadURL();
  print('Uploaded: $downloadUrl');
} on FirebaseException catch (e) {
  // 'storage/unauthorized', 'storage/canceled', 'storage/quota-exceeded'
  print('Upload failed: ${e.code}');
}

// ────── Alternative upload paths ──────
await ref.putData(uint8List, metadata);       // from bytes (web)
await ref.putString(base64, format: PutStringFormat.base64);
await ref.putBlob(webBlob);                    // Flutter web only

// ────── DOWNLOAD ──────

// A) Get URL — cache-friendly, uses signed download tokens.
final url = await ref.getDownloadURL();
// Then use with cached_network_image or Image.network.

// B) Get bytes — for small files or when you need the raw data.
final bytes = await ref.getData(maxSize: 5 * 1024 * 1024);

// C) Download to file — for large files (video, PDF).
final file = File('${(await getTemporaryDirectory()).path}/video.mp4');
final downloadTask = ref.writeToFile(file);
downloadTask.snapshotEvents.listen((snap) {
  print('${snap.bytesTransferred}/${snap.totalBytes}');
});
await downloadTask;

// ────── PAUSE / RESUME / CANCEL ──────
await task.pause();
await task.resume();
await task.cancel();
// Task state persists across app restarts on iOS/Android — resume where left off.

// ────── METADATA ──────
final meta = await ref.getMetadata();
print(meta.contentType);         // 'image/jpeg'
print(meta.size);                // bytes
print(meta.customMetadata);      // your custom fields

// Update metadata (not the file itself):
await ref.updateMetadata(SettableMetadata(customMetadata: {'flagged': 'true'}));

// ────── LIST ──────
