// storage.rules — deployed via `firebase deploy --only storage`
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {

    // Users own their subtree:
    match /users/{uid}/{allFiles=**} {
      allow read: if request.auth.uid == uid;
      allow write: if request.auth.uid == uid
        && request.resource.size < 5 * 1024 * 1024   // 5 MiB max
        && request.resource.contentType.matches('image/(jpeg|png|webp)');
    }

    // Public assets (product images) — anyone reads, only admins write:
    match /products/{productId}/{file} {
      allow read: if true;
      allow write: if request.auth.token.role == 'admin'
        && request.resource.size < 10 * 1024 * 1024
        && request.resource.contentType.matches('image/.*');
    }

    // Chat attachments — participants only:
    match /chats/{chatId}/{file} {
      allow read, write: if request.auth.uid in
        firestore.get(/databases/(default)/documents/chats/$(chatId)).data.participants;
    }

    // Default deny:
    match /{allPaths=**} {
      allow read, write: if false;
    }
  }
}

// KEY: rules can access request.resource (the INCOMING file) for size + contentType
// BEFORE the file is stored — rejects huge uploads at the edge (saves bandwidth $$$).

