// whenever a new image is uploaded. Then client picks the size it needs.

// SOLUTION 2: CDN in front — Cloud CDN, Cloudflare, Fastly.
// Firebase Storage egress ~$0.12/GB. CDN egress ~$0.02-0.05/GB.
// For popular public assets, CDN caches at edge → 90% cheaper + faster.

// SOLUTION 3: Client-side caching.
import 'package:cached_network_image/cached_network_image.dart';

CachedNetworkImage(
  imageUrl: url,
  placeholder: (context, url) => const CircularProgressIndicator(),
  errorWidget: (context, url, error) => const Icon(Icons.error),
  fit: BoxFit.cover,
  width: 100, height: 100,
  memCacheWidth: 200,   // decode at 2x for retina; not full-res!
);
// Caches to disk automatically; only downloads once.

